import $ from 'jquery';
import Ajax from 'core/ajax';
import * as Templates from 'core/templates';
import * as Notification from 'core/notification';
import {get_string as getString} from 'core/str';
import * as FeedReply from 'mod_forum/feed_reply';
import * as Solutions from 'mod_forum/solutions';

/**
 * Read and validate the filter combination from a shareable URL.
 *
 * @param {string} href Full page URL.
 * @param {Set<number>} allowedCourses Courses supplied by the PHP page.
 * @returns {{courseId: number, unread: boolean, following: boolean}} Validated filter state.
 */
export const parseFilters = (href, allowedCourses) => {
    const params = new URL(href).searchParams;
    const rawCourseId = params.get('courseid');
    const requestedCourse = rawCourseId !== null && /^[0-9]+$/.test(rawCourseId)
        ? Number(rawCourseId) : 0;
    const courseId = Number.isSafeInteger(requestedCourse) && allowedCourses.has(requestedCourse)
        ? requestedCourse : 0;
    const following = params.get('following') === '1';
    return {courseId, unread: !following && params.get('unread') === '1', following};
};

/**
 * Initialise the cross-course forum feed and preserve filters in browser history.
 *
 * @param {number} initialCourseId Server-validated initial course.
 * @param {boolean} initialUnread Initial unread-only filter.
 * @param {boolean} initialFollowing Initial starred-only filter.
 */
export const init = (initialCourseId = 0, initialUnread = false, initialFollowing = false) => {
    const root = document.querySelector('[data-region="forum-recent-feed"]');
    if (!root) {
        return;
    }

    const list = root.querySelector('[data-region="feed-items"]');
    const status = root.querySelector('[data-region="feed-status"]');
    const loadMore = root.querySelector('[data-action="feed-more"]');
    const retry = root.querySelector('[data-action="feed-retry"]');
    const allButton = root.querySelector('[data-action="feed-all"]');
    const unreadButton = root.querySelector('[data-action="feed-unread"]');
    const followingButton = root.querySelector('[data-action="feed-following"]');
    const courseSelector = root.querySelector('[data-region="feed-course"]');

    const allowedCourses = new Set(Array.from(courseSelector.options, option => Number(option.value)));
    const initialParams = new URL(window.location.href).searchParams;
    const initialFilters = parseFilters(window.location.href, allowedCourses);
    const state = {
        courseId: initialParams.has('courseid') ? initialFilters.courseId
            : (allowedCourses.has(Number(initialCourseId)) ? Number(initialCourseId) : 0),
        following: initialParams.has('following') ? initialFilters.following : Boolean(initialFollowing),
        unread: (initialParams.has('following') ? initialFilters.following : Boolean(initialFollowing)) ? false :
            (initialParams.has('unread') ? initialFilters.unread : Boolean(initialUnread)),
        cursor: '',
        hasMore: true,
        loading: false,
        generation: 0,
    };

    // All navigation modes use one canonical state. URL changes from user actions
    // create history entries; popstate restoration never writes new entries.
    const updateControls = () => {
        courseSelector.value = String(state.courseId);
        for (const [button, active] of [
            [allButton, !state.unread && !state.following],
            [unreadButton, state.unread],
            [followingButton, state.following],
        ]) {
            button.setAttribute('aria-pressed', String(active));
            button.classList.toggle('btn-primary', active);
            button.classList.toggle('btn-outline-primary', !active);
        }
    };

    const pushFilters = () => {
        const url = new URL(window.location.href);
        if (state.courseId) {
            url.searchParams.set('courseid', String(state.courseId));
        } else {
            url.searchParams.delete('courseid');
        }
        if (state.unread) {
            url.searchParams.set('unread', '1');
        } else {
            url.searchParams.delete('unread');
        }
        if (state.following) {
            url.searchParams.set('following', '1');
        } else {
            url.searchParams.delete('following');
        }
        if (url.href !== window.location.href) {
            window.history.pushState({forumRecentFeed: true}, '', url.pathname + url.search + url.hash);
        }
    };

    /**
     * Load a page. Concurrent results from obsolete filter combinations are
     * rendered in a detached container and discarded before touching the list.
     *
     * @param {boolean} reset Whether to reset the result list and cursor.
     * @returns {Promise<void>}
     */
    const load = async(reset = false) => {
        if (!reset && (state.loading || !state.hasMore)) {
            return;
        }
        if (reset) {
            state.generation++;
            state.cursor = '';
            state.hasMore = true;
            list.replaceChildren();
            loadMore.hidden = true;
            retry.hidden = true;
            updateControls();
        }

        const generation = state.generation;
        const request = {
            courseid: state.courseId, unread: state.unread, cursor: state.cursor,
            following: state.following,
        };
        const previousCount = list.children.length;
        state.loading = true;
        root.setAttribute('aria-busy', 'true');
        loadMore.disabled = true;
        retry.disabled = true;

        try {
            const loadingText = await getString('recentfeedloading', 'mod_forum');
            if (generation !== state.generation) {
                return;
            }
            status.textContent = loadingText;
            const response = await Ajax.call([{
                methodname: 'mod_forum_get_recent_feed',
                args: request,
            }])[0];
            if (generation !== state.generation) {
                return;
            }

            // An empty intermediate cursor page does not require rendering
            // an empty template. It may still contain a continuation cursor.
            if (response.items.length) {
                const [html, js] = await Templates.render('mod_forum/recent_feed_items', response);
                if (generation !== state.generation) {
                    return;
                }
                // Render off-screen so obsolete requests never touch the feed.
                const detached = document.createElement('div');
                await Templates.appendNodeContents($(detached), html, js);
                if (generation !== state.generation) {
                    return;
                }
                list.append(...detached.childNodes);
            }
            state.hasMore = Boolean(response.hasmore && response.nextcursor &&
                response.nextcursor !== request.cursor);
            state.cursor = state.hasMore ? response.nextcursor : '';
            loadMore.hidden = !state.hasMore;
            retry.hidden = true;

            const key = list.children.length === 0 && !state.hasMore
                ? 'recentfeedempty' : 'recentfeedloaded';
            const resultText = key === 'recentfeedempty'
                ? await getString(key, 'mod_forum')
                : await getString(key, 'mod_forum', list.children.length);
            if (generation !== state.generation) {
                return;
            }
            status.textContent = resultText;

            if (!reset && previousCount > 0) {
                const firstNew = list.children[previousCount];
                const link = firstNew && firstNew.querySelector('a');
                if (link) {
                    link.focus();
                }
            }
        } catch (error) {
            if (generation === state.generation) {
                status.textContent = await getString('recentfeederror', 'mod_forum');
                if (generation === state.generation) {
                    retry.hidden = false;
                    loadMore.hidden = true;
                    Notification.exception(error);
                }
            }
        } finally {
            if (generation === state.generation) {
                state.loading = false;
                root.removeAttribute('aria-busy');
                loadMore.disabled = false;
                retry.disabled = false;
            }
        }
    };

    const select = (courseId, unread, following) => {
        if (courseId === state.courseId && unread === state.unread &&
                following === state.following) {
            return;
        }
        state.courseId = courseId;
        state.following = following;
        state.unread = following ? false : unread;
        pushFilters();
        load(true);
    };

    allButton.addEventListener('click', () => select(state.courseId, false, false));
    unreadButton.addEventListener('click', () => select(state.courseId, true, false));
    followingButton.addEventListener('click', () => select(state.courseId, false, true));
    courseSelector.addEventListener('change', () => {
        const id = Number(courseSelector.value);
        select(allowedCourses.has(id) ? id : 0, state.unread, state.following);
    });
    loadMore.addEventListener('click', () => load());
    retry.addEventListener('click', () => load());

    /**
     * Set a discussion's native Moodle star using the existing external API.
     * This affects visual favourites, not subscriptions or notifications.
     *
     * @param {MouseEvent} event Delegated click event.
     * @returns {Promise<void>}
     */
    const toggleFavourite = async(event) => {
        const button = event.target.closest('[data-action="feed-favourite"]');
        if (!button || button.disabled) {
            return;
        }
        const discussionid = Number(button.dataset.discussionId);
        if (!Number.isSafeInteger(discussionid) || discussionid <= 0) {
            return;
        }

        const targetstate = button.dataset.favourited !== '1';
        const generation = state.generation;
        button.disabled = true;
        button.setAttribute('aria-busy', 'true');
        try {
            await Ajax.call([{
                methodname: 'mod_forum_toggle_favourite_state',
                args: {discussionid, targetstate},
            }])[0];

            // If the feed was replaced while the write was pending, the new
            // results must come only from a fresh server response.
            if (generation !== state.generation || !button.isConnected) {
                return;
            }
            const key = targetstate ? 'recentfeedunfollow' : 'recentfeedfollow';
            const label = await getString(key, 'mod_forum');
            if (generation !== state.generation || !button.isConnected) {
                return;
            }
            button.dataset.favourited = targetstate ? '1' : '0';
            button.setAttribute('aria-pressed', String(targetstate));
            button.setAttribute('aria-label', label);
            button.querySelector('[data-region="favourite-label"]').textContent = label;
            button.querySelector('[data-region="favourite-symbol"]').textContent = targetstate ? '★' : '☆';

            if (state.following && !targetstate) {
                const card = button.closest('[data-post-id]');
                const next = card.nextElementSibling || card.previousElementSibling;
                card.remove();
                const focusTarget = next && next.querySelector('a');
                if (focusTarget) {
                    focusTarget.focus();
                } else {
                    followingButton.focus();
                }
            }
            const feedbackkey = state.following && list.children.length === 0 && !state.hasMore ?
                'recentfeedempty' : 'recentfeedfavouriteupdated';
            const message = await getString(feedbackkey, 'mod_forum');
            if (generation === state.generation) {
                status.textContent = message;
            }
        } catch (error) {
            if (generation === state.generation && button.isConnected) {
                status.textContent = await getString('recentfeedfavouriteerror', 'mod_forum');
                Notification.exception(error);
            }
        } finally {
            if (button.isConnected) {
                button.disabled = false;
                button.removeAttribute('aria-busy');
            }
        }
    };
    list.addEventListener('click', toggleFavourite);

    const restoreFilters = () => {
        const previous = parseFilters(window.location.href, allowedCourses);
        state.courseId = previous.courseId;
        state.unread = previous.unread;
        state.following = previous.following;
        load(true);
    };
    window.addEventListener('popstate', restoreFilters);
    window.addEventListener('pageshow', event => {
        if (event.persisted) {
            restoreFilters();
        }
    });

    Solutions.initFeed(root, () => load(true));

    FeedReply.init(root, async(response) => {
        // A successful native publication must not reset course or tab filters.
        // The new direct link remains accessible even if the post is no
        // longer present on the first page of the selected feed filter.
        await load(true);
        const message = await getString('recentfeedreplysent', 'mod_forum');
        status.textContent = message + ' ';
        const link = document.createElement('a');
        link.href = response.url;
        link.textContent = await getString('recentfeedviewreply', 'mod_forum');
        status.append(link);
        link.focus();
    });

    updateControls();
    // The first page load does not rewrite the URL or create history entries.
    load(true);
};
